import pytest

from date_utils import days_in_month


def test_days_in_month_all_months_non_leap():
    """Verify exact day counts for every month in a non-leap year (2023)."""
    expected = {
        1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
        7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31,
    }
    for m, d in expected.items():
        assert days_in_month(2023, m) == d, f"month {m}"


def test_days_in_month_all_months_leap():
    """Verify exact day counts for every month in a leap year (2024)."""
    expected = {
        1: 31, 2: 29, 3: 31, 4: 30, 5: 31, 6: 30,
        7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31,
    }
    for m, d in expected.items():
        assert days_in_month(2024, m) == d, f"month {m}"


def test_days_in_month_invalid_low():
    """Month 0 and negative months must raise ValueError."""
    with pytest.raises(ValueError):
        days_in_month(2023, 0)
    with pytest.raises(ValueError):
        days_in_month(2023, -1)


def test_days_in_month_invalid_high():
    """Month 13 and above must raise ValueError."""
    with pytest.raises(ValueError):
        days_in_month(2023, 13)
    with pytest.raises(ValueError):
        days_in_month(2023, 14)

