import pytest
from validators import validate_username


class TestValidateUsername:
    def test_minimum_length_valid(self):
        assert validate_username("abc") == "abc"

    def test_maximum_length_valid(self):
        name = "a" + "b" * 15
        assert len(name) == 16
        assert validate_username(name) == name

    def test_too_short_raises(self):
        with pytest.raises(ValueError):
            validate_username("ab")

    def test_too_long_raises(self):
        with pytest.raises(ValueError):
            validate_username("a" * 17)

    def test_starts_with_digit_raises(self):
        with pytest.raises(ValueError):
            validate_username("1abc")

    def test_starts_with_underscore_raises(self):
        with pytest.raises(ValueError):
            validate_username("_abc")

    def test_illegal_char_raises(self):
        with pytest.raises(ValueError):
            validate_username("ab-c")

    def test_valid_with_digits_and_underscore(self):
        assert validate_username("a1_b") == "a1_b"

    def test_return_is_unmodified(self):
        name = "User_123"
        assert validate_username(name) == name

